async function wlRefresh(){ const p = $('tcWl'); if(!S || !p || !p.classList.contains('on')) return; try{ S.list[S.ex] = (await EX[S.ex].list()).sort((a, b) => b.vol - a.vol); wlRender(); }catch(e){} }
